          q: "ਪੈਰਾ ਪੜ੍ਹ ਕੇ ਪ੍ਰਸ਼ਨਾਂ ਦੇ ਉੱਤਰ ਦਿਓ: 'ਪਾਣੀ ਕੁਦਰਤ ਦੀ ਅਨਮੋਲ ਦਾਤ ਹੈ। ਇਸ ਤੋਂ ਬਿਨਾਂ ਮਨੁੱਖ, ਪਸ਼ੂ-ਪੰਛੀ ਅਤੇ ਰੁੱਖ-ਬੂਟੇ ਜਿਉਂਦੇ ਨਹੀਂ ਰਹਿ ਸਕਦੇ। ਪਰ ਅਸੀਂ ਬਿਨਾਂ ਸੋਚੇ ਪਾਣੀ ਵਿਅਰਥ ਗੁਆ ਰਹੇ ਹਾਂ। ਟੂਟੀਆਂ ਖੁੱਲ੍ਹੀਆਂ ਛੱਡਣਾ ਅਤੇ ਲੋੜ ਤੋਂ ਵੱਧ ਪਾਣੀ ਵਰਤਣਾ ਆਮ ਗੱਲ ਬਣ ਗਈ ਹੈ। ਜੇ ਅਸੀਂ ਅੱਜ ਪਾਣੀ ਦੀ ਸੰਭਾਲ ਨਾ ਕੀਤੀ ਤਾਂ ਆਉਣ ਵਾਲੀਆਂ ਪੀੜ੍ਹੀਆਂ ਨੂੰ ਇਸ ਦੀ ਭਾਰੀ ਘਾਟ ਝੱਲਣੀ ਪਵੇਗੀ।' (ੳ) ਪਾਣੀ ਨੂੰ ਅਨਮੋਲ ਦਾਤ ਕਿਉਂ ਕਿਹਾ ਗਿਆ ਹੈ? (ਅ) ਪਾਣੀ ਕਿਵੇਂ ਵਿਅਰਥ ਗੁਆਇਆ ਜਾ ਰਿਹਾ ਹੈ? (ੲ) 'ਵਿਅਰਥ' ਦਾ ਅਰਥ ਦੱਸੋ। (ਸ) ਪੈਰੇ ਦਾ ਢੁਕਵਾਂ ਸਿਰਲੇਖ ਲਿਖੋ।",
