        { q: "'ਸਮਾਂ' ਕਵਿਤਾ ਅਨੁਸਾਰ ਲੰਘਿਆ ਹੋਇਆ ਸਮਾਂ ਕੀ ਕਰਦਾ ਹੈ?", options: ["ਮੁੜ ਆ ਜਾਂਦਾ ਹੈ", "ਕੁਝ ਦੇਰ ਰੁਕਦਾ ਹੈ", "ਮੁੜ ਕੇ ਨਹੀਂ ਆਉਂਦਾ", "ਹੌਲੀ ਹੋ ਜਾਂਦਾ ਹੈ"], answer: 2, explain: "ਕਵੀ ਕਹਿੰਦਾ ਹੈ ਕਿ ਲੰਘਿਆ ਸਮਾਂ ਮੁੜ ਨਹੀਂ ਆਉਂਦਾ।" },
        { q: "ਬਿਨਫ਼ਸ਼ਾ ਦਾ ਫੁੱਲ ਆਪਣੀ ਪਛਾਣ ਕਿਸ ਕਾਰਨ ਛੁਪਾ ਨਹੀਂ ਸਕਦਾ?", options: ["ਆਪਣੇ ਰੰਗ ਕਾਰਨ", "ਆਪਣੀ ਉਚਾਈ ਕਾਰਨ", "ਆਪਣੀ ਖ਼ੁਸ਼ਬੋ ਕਾਰਨ", "ਆਪਣੇ ਕੰਡਿਆਂ ਕਾਰਨ"], answer: 2, explain: "ਫੁੱਲ ਲੁਕਣਾ ਚਾਹੁੰਦਾ ਹੈ ਪਰ ਖ਼ੁਸ਼ਬੋ ਉਸ ਦਾ ਭੇਤ ਖੋਲ੍ਹ ਦਿੰਦੀ ਹੈ।" },
        { q: "'ਟੁਕੜੀ ਜੱਗ ਤੋਂ ਨਿਆਰੀ' ਕਵਿਤਾ ਵਿੱਚ ਕਿਸ ਥਾਂ ਦੀ ਸੁੰਦਰਤਾ ਦਾ ਵਰਨਣ ਹੈ?", options: ["ਹਿਮਾਚਲ", "ਕਸ਼ਮੀਰ", "ਪੰਜਾਬ", "ਸ਼ਿਮਲਾ"], answer: 1, explain: "ਮੁੱਠੀ ਜਿੱਥੇ ਡਿੱਗੀ ਉੱਥੇ ਕਸ਼ਮੀਰ ਬਣਿਆ।" },
        { q: "ਕਵੀ ਧਰਤੀ ਦੇ ਲੋਕਾਂ ਨੂੰ 'ਤੰਗ-ਦਿਲ' ਕਿਉਂ ਕਹਿੰਦਾ ਹੈ?", options: ["ਉਹ ਗ਼ਰੀਬ ਹਨ", "ਉਹ ਗਿੱਠ ਥਾਂ ਲਈ ਲੜਦੇ ਹਨ", "ਉਹ ਪਹਾੜਾਂ ਵਿੱਚ ਰਹਿੰਦੇ ਹਨ", "ਉਹ ਸਫ਼ਰ ਨਹੀਂ ਕਰਦੇ"], answer: 1, explain: "ਅਸਮਾਨ ਦੀ ਵਿਸ਼ਾਲਤਾ ਸਾਹਮਣੇ ਜ਼ਮੀਨ ਦੇ ਟੁਕੜੇ ਲਈ ਝਗੜਨਾ ਛੋਟੀ ਸੋਚ ਹੈ।" }
