          "'ਵਹਿੰਦਾ ਜਾਏ' ਵਿੱਚ ਨਦੀ ਦਾ ਪਾਣੀ ਲਗਾਤਾਰ ਚੱਲਦਾ ਹੈ; ਅਸਮਾਨ ਦਾ ਤਾਰਾ ਲਹਿਰਾਂ ਵਿੱਚ ਝਲਕਾਰਾ ਪਾ ਕੇ ਕਹਿੰਦਾ ਹੈ ਕਿ ਤੇਰਾ ਪੰਧ ਲੰਮਾ ਹੈ।",
