        { q: "'ਵਿਸਾਖੀ ਦਾ ਮੇਲਾ' ਵਿੱਚ ਮੇਲੇ ਦੀ ਰੌਣਕ ਕਿਵੇਂ ਦਰਸਾਈ ਹੈ?", a: "ਵਣਜਾਰੇ ਵੰਗਾਂ ਤੇ ਗਜਰੇ ਲਿਆਉਂਦੇ ਹਨ, ਹਲਵਾਈਆਂ ਦੀਆਂ ਹੱਟੀਆਂ ਤੇ ਪੰਘੂੜੇ ਹਨ, ਜੋਗੀ-ਮਦਾਰੀ ਤਮਾਸ਼ੇ ਕਰਦੇ ਹਨ, ਛਿੰਝ ਵਿੱਚ ਪਹਿਲਵਾਨ ਗੱਜਦੇ ਹਨ ਅਤੇ ਭਾਰੀ ਭੀੜ ਹੈ।" },
        { q: "'ਜੀਵਨ-ਜੋਤ' ਕਵਿਤਾ ਮਨੁੱਖ ਨੂੰ ਕੀ ਪ੍ਰੇਰਨਾ ਦਿੰਦੀ ਹੈ?", a: "ਇਹ ਮਨੁੱਖ ਨੂੰ ਸੁਸਤੀ ਛੱਡ ਕੇ ਹਿੰਮਤ ਨਾਲ ਅਜਿਹਾ ਜੀਵਨ ਜਿਊਣ ਦੀ ਪ੍ਰੇਰਨਾ ਦਿੰਦੀ ਹੈ ਜੋ ਦੂਜਿਆਂ ਲਈ ਰੌਸ਼ਨੀ ਬਣੇ ਅਤੇ ਮਰਨ ਪਿੱਛੋਂ ਵੀ ਯਾਦ ਰਹੇ।" }
