          "ਉਹਨਾਂ ਨੇ 'ਸ਼ਹੀਦ' ਅਖ਼ਬਾਰ ਕੱਢਿਆ ਅਤੇ 'ਮੌਜੀ' ਤੇ 'ਹੰਸ' ਪੱਤਰਾਂ ਦਾ ਸੰਪਾਦਨ ਕੀਤਾ।",
          "ਉਹਨਾਂ ਦੀਆਂ ਕਵਿਤਾਵਾਂ **ਹਾਸ-ਰਸ ਭਰਪੂਰ ਪਰ ਸਿੱਖਿਆਦਾਇਕ** ਹਨ ਅਤੇ ਉਹ ਆਪਣਾ ਉਪਨਾਮ 'ਸੁਥਰਾ' ਵਰਤਦੇ ਸਨ; ਨਾਂ ਅੱਗੇ 'ਸ. ਸ.' ਉਹਨਾਂ ਦੇ ਪਿਤਾ ਸੂਬਾ ਸਿੰਘ ਦੇ ਨਾਂ ਵੱਲ ਇਸ਼ਾਰਾ ਹੈ।"
