          "ਸਵਾਲ: ਜੇ ਸੌ ਕੋਹ ਤੱਕ ਪਾਣੀ ਨਾ ਮਿਲੇ ਅਤੇ ਕੋਈ ਪਿਆਲਾ ਲਿਆ ਦੇਵੇ ਤਾਂ ਤੁਸੀਂ ਕੀ ਦਿਓਗੇ? ਅਕਬਰ ਨੇ ਕਿਹਾ ਕਿ ਮੈਂ ਅੱਧਾ ਰਾਜ ਦੇ ਦਿਆਂਗਾ।",
          "ਪਾਣੀ ਪੀਣ ਪਿੱਛੋਂ ਬੀਰਬਲ ਨੇ ਦੂਜਾ ਸਵਾਲ ਪੁੱਛਿਆ: ਜੇ ਪਾਣੀ ਸਰੀਰ ਅੰਦਰ ਰੁਕ ਜਾਵੇ ਤਾਂ ਇਲਾਜ ਲਈ ਕੀ ਦਿਓਗੇ? ਅਕਬਰ ਨੇ ਫਿਰ ਅੱਧਾ ਰਾਜ ਦੇਣਾ ਮੰਨਿਆ।",
          "ਬੀਰਬਲ ਨੇ ਸਿੱਟਾ ਕੱਢਿਆ ਕਿ ਇੱਕ ਪਿਆਲੇ ਜਲ ਦਾ ਮੁੱਲ ਸਾਰਾ ਰਾਜ ਹੈ; ਕੇਂਦਰੀ ਭਾਵ ਹੈ ਕਿ **ਰੱਬ ਦੀ ਮੁਫ਼ਤ ਬਖ਼ਸ਼ਿਸ਼ ਦਾ ਮੁੱਲ ਕੋਈ ਨਹੀਂ ਪਾ ਸਕਦਾ**, ਇਸ ਲਈ ਉਸ ਦਾ ਸ਼ੁਕਰ ਕਰਨਾ ਚਾਹੀਦਾ ਹੈ।"
