          "ਕੰਗਾਲ ਧਨੀਆਂ ਦੀ ਰੀਸ ਕਰ ਕੇ ਕਰਜ਼ੇ ਵਿੱਚ ਫਸਦਾ ਹੈ ਅਤੇ ਕਮਜ਼ੋਰ ਤਕੜੇ ਨਾਲ ਖਹਿ ਕੇ ਹੱਡ ਤੁੜਵਾ ਲੈਂਦਾ ਹੈ।",
