        { q: "'ਇੱਕ ਪਿਆਲਾ ਪਾਣੀ' ਵਿੱਚ ਬੀਰਬਲ ਨੇ ਕਿਸ ਬਾਦਸ਼ਾਹ ਨੂੰ ਸਵਾਲ ਪੁੱਛੇ?", options: ["ਬਾਬਰ", "ਅਕਬਰ", "ਜਹਾਂਗੀਰ", "ਸ਼ਾਹਜਹਾਨ"], answer: 1, explain: "ਪ੍ਰਸੰਗ ਅਕਬਰ ਤੇ ਬੀਰਬਲ ਦਾ ਹੈ।" },
        { q: "ਅਕਬਰ ਨੇ ਪਿਆਲੇ ਪਾਣੀ ਬਦਲੇ ਕੀ ਦੇਣਾ ਮੰਨਿਆ?", options: ["ਇੱਕ ਹਾਥੀ", "ਅੱਧਾ ਰਾਜ", "ਸੌ ਮੋਹਰਾਂ", "ਇੱਕ ਮਹਿਲ"], answer: 1, explain: "ਦੋਵੇਂ ਵਾਰ ਉਸ ਨੇ ਅੱਧਾ ਰਾਜ ਦੇਣਾ ਮੰਨਿਆ।" },
        { q: "'ਗ਼ਲਤ-ਫ਼ਹਿਮੀਆਂ' ਅਨੁਸਾਰ ਸ਼ੈਤਾਨ ਦੀ ਗ਼ਲਤੀ ਕੀ ਸੀ?", options: ["ਚੋਰੀ", "ਹੰਕਾਰ ਵਿੱਚ ਆਦਮ ਦਾ ਆਦਰ ਨਾ ਕਰਨਾ", "ਝੂਠ ਬੋਲਣਾ", "ਆਲਸ"], answer: 1, explain: "ਉਹ ਆਪਣੇ ਆਪ ਨੂੰ ਵੱਡਾ ਸਮਝ ਕੇ ਆਦਮ ਦੇ ਸਾਹਮਣੇ ਨਾ ਝੁਕਿਆ।" },
        { q: "ਕਵੀ ਅਨੁਸਾਰ ਭਰਮ ਛੱਡਣ ਨਾਲ ਸੰਸਾਰ ਕਿਹੋ-ਜਿਹਾ ਹੋ ਜਾਵੇਗਾ?", options: ["ਨਰਕ", "ਸੁਰਗ", "ਮਾਰੂਥਲ", "ਜੰਗਲ"], answer: 1, explain: "ਭਰਮ ਛੱਡ ਕੇ ਬਰਾਬਰੀ ਮੰਨਣ ਨਾਲ ਜੱਗ ਸੁਰਗ ਬਣ ਸਕਦਾ ਹੈ।" }
