          "ਅੰਡੇਮਾਨ ਵਿੱਚ ਜਪਾਨੀ ਹਮਲੇ ਸਮੇਂ ਤਸੀਹੇ ਦੇ ਕੇ ਉਹਨਾਂ ਨੂੰ ਸ਼ਹੀਦ ਕਰ ਦਿੱਤਾ ਗਿਆ; ਕਾਵਿ-ਸੰਗ੍ਰਹਿ: ਵਗਦੇ ਪਾਣੀ, ਅੰਤਿਮ ਲਹਿਰਾਂ, ਮੇਰਾ ਜੀਵਨ ਮੇਰਾ ਗੀਤ, ਸਹਜ ਸੰਚਾਰ, ਮਲ੍ਹਿਆਂ ਦੇ ਬੇਰ।"
