        { q: "ਕਵਿਤਰੀ ਨੇ 'ਤ੍ਰਿੰਵਣ' ਦਾ ਜੋ ਚਿੱਤਰ ਪੇਸ਼ ਕੀਤਾ ਹੈ, ਉਸ ਨੂੰ ਆਪਣੇ ਸ਼ਬਦਾਂ ਵਿੱਚ ਲਿਖੋ।", a: "ਸਹੇਲੀਆਂ ਬਣ-ਸੰਵਰ ਕੇ ਚਰਖ਼ੇ ਲੈ ਕੇ ਤ੍ਰਿੰਵਣ ਵਿੱਚ ਆਉਂਦੀਆਂ ਹਨ। ਹਰ ਕੁੜੀ ਨੇ ਵੱਖਰੇ ਰੰਗ ਦੇ ਕੱਪੜੇ, ਗਜਰੇ ਅਤੇ ਸੂਹੀ ਫੁਲਕਾਰੀ ਪਹਿਨੀ ਹੈ। ਉਹ ਭੁੰਨੇ ਦਾਣੇ, ਖਿੱਲਾਂ ਤੇ ਸੱਤੂ ਲਿਆ ਕੇ ਰਲ-ਮਿਲ ਕੇ ਕੱਤਦੀਆਂ ਤੇ ਹੱਸਦੀਆਂ ਹਨ।" },
        { q: "'ਅਹਿਦਨਾਮਾ' ਕਵਿਤਾ ਵਿੱਚ ਕਿਸ ਅਹਿਦਨਾਮੇ ਉੱਤੇ ਦਸਖ਼ਤ ਕਰਨ ਲਈ ਕਿਹਾ ਗਿਆ ਹੈ?", a: "ਅਮਨ ਦੇ ਅਹਿਦਨਾਮੇ 'ਤੇ, ਜਿਸ ਵਿੱਚ ਨਫ਼ਰਤ ਛੱਡ ਕੇ ਪਿਆਰ ਅਤੇ ਸ਼ਾਂਤੀ ਨਾਲ ਰਹਿਣ ਦਾ ਇਕਰਾਰ ਹੈ।" },
        { q: "'ਅਹਿਦਨਾਮਾ' ਵਿੱਚ ਦਸਖ਼ਤ ਕਰਨ ਲਈ ਕਿਹੜੇ ਲੋਕਾਂ ਨੂੰ ਸੱਦਾ ਦਿੱਤਾ ਹੈ?", a: "ਦੁਨੀਆ ਵਾਲਿਆਂ, ਹੁਸਨ ਤੇ ਹੁਨਰ ਦੇ ਵਣਜਾਰਿਆਂ, ਦੀਨ-ਈਮਾਨ ਵਾਲਿਆਂ, ਨੇਮਾਂ-ਧਰਮਾਂ ਵਾਲਿਆਂ ਅਤੇ ਕਰਮਾਂ ਵਾਲਿਆਂ ਨੂੰ।" }
