        { q: "ਅੰਮ੍ਰਿਤਾ ਪ੍ਰੀਤਮ ਦੀ ਕਿਹੜੀ ਰਚਨਾ ਨੂੰ ਗਿਆਨਪੀਠ ਪੁਰਸਕਾਰ ਮਿਲਿਆ?", options: ["ਕਾਗ਼ਜ਼ ਤੇ ਕੈਨਵਸ", "ਸੁਨੇਹੜੇ", "ਲੋਕ ਪੀੜ", "ਕਸਤੂਰੀ"], answer: 0, explain: "'ਕਾਗ਼ਜ਼ ਤੇ ਕੈਨਵਸ' ਨੂੰ ਗਿਆਨਪੀਠ ਪੁਰਸਕਾਰ ਮਿਲਿਆ।" },
        { q: "ਅੰਮ੍ਰਿਤਾ ਪ੍ਰੀਤਮ ਨੇ ਕਿਹੜਾ ਰਿਸਾਲਾ ਕੱਢਿਆ?", options: ["ਨਾਗਮਣੀ", "ਪੰਜ ਦਰਿਆ", "ਹੰਸ", "ਸ਼ਹੀਦ"], answer: 0, explain: "ਉਹਨਾਂ ਨੇ 'ਨਾਗਮਣੀ' ਰਿਸਾਲਾ ਕੱਢਿਆ।" },
        { q: "'ਤ੍ਰਿੰਵਣ' ਵਿੱਚ ਕੁੜੀਆਂ ਇੱਕ ਹੱਥ ਚਰਖ਼ਾ ਅਤੇ ਦੂਜੇ ਹੱਥ ਕੀ ਲੈ ਕੇ ਆਉਂਦੀਆਂ ਹਨ?", options: ["ਪੱਛੀ", "ਘੜਾ", "ਗਾਗਰ", "ਛਤਰੀ"], answer: 0, explain: "ਇੱਕ ਹੱਥ ਚਰਖ਼ਾ ਅਤੇ ਇੱਕ ਹੱਥ ਪੱਛੀ ਹੈ।" },
        { q: "'ਅਹਿਦਨਾਮਾ' ਕਵਿਤਾ ਦਾ ਮੁੱਖ ਸੁਨੇਹਾ ਕੀ ਹੈ?", options: ["ਨਫ਼ਰਤ ਛੱਡ ਕੇ ਅਮਨ ਦਾ ਇਕਰਾਰ ਕਰੋ", "ਜੰਗ ਦੀ ਤਿਆਰੀ ਕਰੋ", "ਵਪਾਰ ਵਧਾਓ", "ਚੁੱਪ ਰਹੋ"], answer: 0, explain: "ਕਵਿਤਾ ਅਮਨ ਦੇ ਇਕਰਾਰਨਾਮੇ ਉੱਤੇ ਦਸਖ਼ਤ ਕਰਵਾਉਂਦੀ ਹੈ।" }
