          "ਪ੍ਰਸਿੱਧ ਕਾਵਿ-ਪੁਸਤਕਾਂ: ਪੀੜਾਂ ਦਾ ਪਰਾਗਾ, ਲਾਜਵੰਤੀ, ਆਟੇ ਦੀਆਂ ਚਿੜੀਆਂ, ਮੈਨੂੰ ਵਿਦਾ ਕਰੋ, ਲੂਣਾ, ਆਰਤੀ; 'ਲੂਣਾ' ਨੂੰ ਸਾਹਿਤ ਅਕਾਦਮੀ ਪੁਰਸਕਾਰ ਮਿਲਿਆ ਅਤੇ ਭਰ-ਜਵਾਨੀ ਵਿੱਚ 1973 ਵਿੱਚ ਉਹਨਾਂ ਦਾ ਦਿਹਾਂਤ ਹੋ ਗਿਆ।"
