          "ਉਸ ਨੂੰ ਆਪਣਾ ਕੋਈ ਵੀ ਗੀਤ ਬੁਜ਼ਦਿਲ ਲੱਗਦਾ ਹੈ, ਕਿਉਂਕਿ ਉਹ ਨੀਹਾਂ ਵਿੱਚ ਚਿਣੇ ਜਾਣ ਤੇ ਸੀਸ ਵਾਰਨ ਵਰਗੀ ਕੁਰਬਾਨੀ ਦੇ ਸਾਹਮਣੇ ਖੜ੍ਹੇ ਹੋਣ ਦੇ ਕਾਬਲ ਨਹੀਂ।",
