        { q: "ਪਾਂਡਾ ਭੋਲੀਆਂ-ਭਾਲੀਆਂ ਔਰਤਾਂ ਨੂੰ ਕਿਵੇਂ ਲੁੱਟਦਾ ਹੈ?", a: "ਪਾਂਡਾ ਪਹਿਲਾਂ ਘਰ ਦੇ ਬੱਚਿਆਂ ਦੇ ਨਾਂ ਪੁੱਛ ਲੈਂਦਾ ਹੈ, ਫਿਰ ਹੱਥ ਵੇਖ ਕੇ ਉਹੀ ਨਾਂ ਦੱਸ ਕੇ ਸੱਚਾ ਬਣ ਜਾਂਦਾ ਹੈ। ਉਹ ਬਿਪਤਾ ਦਾ ਡਰ ਦਿਖਾ ਕੇ ਦਾਨ ਮੰਗਦਾ ਹੈ ਅਤੇ ਹੋਰ ਔਰਤਾਂ ਤੋਂ ਵੀ ਗਹਿਣੇ ਲੈ ਜਾਂਦਾ ਹੈ।" },
        { q: "'ਮਨ ਚੰਗਾ ਤਾਂ ਕਠੋਤੀ ਵਿੱਚ ਗੰਗਾ' ਅਖਾਣ ਦਾ ਕੀ ਭਾਵ ਹੈ?", a: "ਜੇ ਮਨ ਪਵਿੱਤਰ ਹੋਵੇ ਤਾਂ ਹਰ ਥਾਂ ਹੀ ਤੀਰਥ ਹੈ; ਯਾਨੀ ਅਸਲ ਪਵਿੱਤਰਤਾ ਮਨ ਦੀ ਹੁੰਦੀ ਹੈ, ਬਾਹਰੀ ਦਿਖਾਵੇ ਦੀ ਨਹੀਂ।" }
