          "ਫਿਰ ਕੀਟਾਣੂਆਂ ਦਾ ਵਹਿਮ ਹੋਇਆ: ਉਹ ਹੱਥ ਮਿਲਾ ਕੇ ਅੱਧਾ ਘੰਟਾ ਹੱਥ ਧੋਂਦਾ, ਕੁਰਸੀ-ਚਾਦਰਾਂ ਉਬਾਲਦਾ ਅਤੇ ਇੱਕ ਗੁਆਂਢੀ ਬੱਚੇ ਦਾ ਮੂੰਹ ਚੁੰਮਣ ਉੱਤੇ ਉਸ ਨੂੰ ਸਾਬਣ ਨਾਲ ਘਸਾ-ਘਸਾ ਕੇ ਲਹੂ ਕੱਢ ਛੱਡਿਆ, ਜਿਸ ਕਾਰਨ ਲਾਠੀਆਂ ਖਾਣ ਦੀ ਨੌਬਤ ਆਈ।",
