          "ਆਪਣਾ ਗੁਨਾਹ ਕਬੂਲ ਕਰ ਕੇ ਮਾਫ਼ੀ ਮੰਗਣ, ਨੁਕਸਾਨ ਦੀ ਭਰਪਾਈ ਕਰਨ ਅਤੇ ਦੁਸ਼ਮਣ ਨੂੰ ਮਾਫ਼ ਕਰਨ ਨਾਲ ਮਨ ਦਾ ਭਾਰ ਹੌਲਾ ਹੁੰਦਾ ਹੈ।",
