          "ਉਹ ਪਰਿਵਾਰ ਨੂੰ ਇੱਕ-ਦੂਜੇ ਨਾਲ ਜੋੜਨ ਵਾਲੀ ਕੜੀ ਹੈ; ਉਸ ਤੋਂ ਬਿਨਾਂ 'ਇੱਕ ਰਾਜਧਾਨੀ ਟੁੱਟ ਜਾਏਗੀ'।",
          "ਛੋਟਾ ਭਰਾ ਬਿਰਧ ਮਾਪਿਆਂ ਦੀ ਸੇਵਾ ਕਰਦਾ ਹੈ ਅਤੇ ਪੁੱਛਦਾ ਹੈ, 'ਜਦੋਂ ਬੇਬੇ-ਬਾਪੂ ਨਾ ਰਹੇ ਤਦ ਵੀ ਆਇਆ ਕਰੋਗੇ?'; ਲੇਖਕ ਨੂੰ ਸੁਪਨਿਆਂ ਵਿੱਚ ਬੇਬੇ ਖੇਤਾਂ ਵਿੱਚ ਕੰਮ ਕਰਦੀ ਦਿਸਦੀ ਹੈ।"
